const stars=Array.from({length:110},()=>({x:Math.random(),y:Math.random(),r:Math.random()*1.3+.2,s:Math.random()*.0002+.00003,a:Math.random()}));
const t=(1+Math.sqrt(5))/2;
const V=[[-1,t,0],[1,t,0],[-1,-t,0],[1,-t,0],[0,-1,t],[0,1,t],[0,-1,-t],[0,1,-t],[t,0,-1],[t,0,1],[-t,0,-1],[-t,0,1]];
const E=[];for(let i=0;i<12;i++)for(let j=i+1;j<12;j++){const d=Math.hypot(V[i][0]-V[j][0],V[i][1]-V[j][1],V[i][2]-V[j][2]);if(Math.abs(d-2)<.01)E.push([i,j])}
const shapes=Array.from({length:9},(_,i)=>({x:Math.random(),y:Math.random(),z:Math.random()*.6+.4,sz:Math.random()*50+35,rx:Math.random()*6,ry:Math.random()*6,vx:(Math.random()-.5)*.012,vy:(Math.random()-.5)*.012,knot:i%3===0,ph:Math.random()*6}));
function proj(p,a,b,s,cx,cy){let[x,y,z]=p;let c=Math.cos(a),n=Math.sin(a);[y,z]=[y*c-z*n,y*n+z*c];c=Math.cos(b);n=Math.sin(b);[x,z]=[x*c+z*n,-x*n+z*c];const f=3/(3+z*.4);return[cx+x*s*f,cy+y*s*f]}
let sy=0;addEventListener('scroll',()=>sy=scrollY,{passive:true});
function draw(ts){ctx.clearRect(0,0,W,H);
 stars.forEach(s=>{s.y=(s.y+s.s*16)%1;ctx.globalAlpha=.25+.5*Math.abs(Math.sin(ts*.0008+s.a*9));ctx.fillStyle='#caa';ctx.beginPath();ctx.arc(s.x*W,s.y*H,s.r,0,7);ctx.fill()});
 shapes.forEach(s=>{s.rx+=s.vx;s.ry+=s.vy;
  const cx=s.x*W+(mx-W/2)*.02*s.z,cy=((s.y*H*1.6-sy*s.z*.35)%(H*1.3)+H*1.3)%(H*1.3)-H*.15+Math.sin(ts*.0006+s.ph)*14;
  ctx.globalAlpha=.5*s.z;ctx.strokeStyle='#a01212';ctx.lineWidth=1.2;
  if(!s.knot){ctx.beginPath();E.forEach(([i,j])=>{const a=proj(V[i],s.rx,s.ry,s.sz*.5,cx,cy),b=proj(V[j],s.rx,s.ry,s.sz*.5,cx,cy);ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1])});ctx.stroke()}
  else{ctx.lineWidth=3.5;ctx.strokeStyle='#8b0000';ctx.beginPath();for(let k=0;k<=120;k++){const u=k/120*Math.PI*2,p=[Math.sin(u)+2*Math.sin(2*u),Math.cos(u)-2*Math.cos(2*u),-Math.sin(3*u)];const q=proj(p,s.rx,s.ry,s.sz*.28,cx,cy);k?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1])}ctx.stroke()}
 });ctx.globalAlpha=1;requestAnimationFrame(draw)}
requestAnimationFrame(draw);

